INSERT INTO `everlake_build_stage` (`n`, `ID`, `RewardText`) VALUES
(1, 94254, 'My new robe! Delightful!$B$BAt long last, I can don my robe AND my wizard hat.'),
(2, 94302, 'My new home is surrounded by turtles, yet I have no knowledge of how to properly prepare their meat nor craft equipment with their scales.$B$BAs shameful as it feels, my survival has depended upon the aid of others outside my tribe. I have been humbled by the kindness of strangers, and humbled by the simple yet effective techniques they have taught me.$B$BI hope to learn from this turtle scale breastplate in much the same way.')
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) SELECT p.`ID`, p.`RewardText`, 0 FROM `everlake_build_stage` p WHERE p.`free` = 1 ORDER BY p.`n`;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_offer_reward', p.`ID`, '2026_11_19_981_world_everlake_build.sql', s.`note` FROM `everlake_build_stage` p JOIN `everlake_build_quests` s ON s.`ID` = p.`ID` WHERE p.`free` = 1;
INSERT INTO `everlake_build_stage` (`n`, `ID`, `CompletionText`) VALUES
(1, 94254, '<Magus Tirth begins to cast Polymorph: Chicken on you.>'),
(2, 94302, '<The $r woman acknowledges you with a glare, but allows you to approach nonetheless.>')
